-- Grammar facts seed: 50 facts per course for the "grammar" context.
-- These appear in LgLumiFact when context='grammar' (grammar training screens).

INSERT INTO lumi_facts (course_code, context, locale, body)
SELECT 'en_ru', 'grammar', 'ru', f.body
FROM (VALUES
    ('В английском нет падежей существительных — слова не изменяются по родительному, дательному или винительному. Порядок слов в предложении заменяет всю падежную систему.'),
    ('Глагол «be» — самый неправильный в английском: I am / you are / he is / was / were — каждая форма из разного корня. Это следы трёх разных праиндоевропейских глаголов.'),
    ('Present Continuous (I am reading) появился в английском примерно в XIV веке под влиянием кельтских языков Британии. В большинстве германских языков такой формы нет.'),
    ('Present Perfect (I have done) — «память» английского: действие в прошлом, но связь с настоящим не порвана. Русский так точно не разграничивает: «Я сделал» покрывает оба смысла.'),
    ('«Do»-вспомогательный глагол уникален для английского среди европейских языков: в немецком, французском, испанском вопросы строятся иначе — без отдельного «do».'),
    ('Артикли (a/an/the) появились в английском из демонстративного местоимения «that». Постепенно «that» сократилось до «the», а «one» — до «a/an».'),
    ('Фраза «I could care less» неправильна по логике — правильно «I couldn''t care less» (мне так безразлично, что меньше некуда). Но неверная версия настолько укоренилась, что многие носители её не замечают.'),
    ('Герундий (-ing форма) и инфинитив (to + глагол) часто взаимозаменяемы, но не всегда: «I stopped smoking» (бросил курить) ≠ «I stopped to smoke» (остановился, чтобы покурить).'),
    ('В английском три степени сравнения: положительная (fast), сравнительная (faster), превосходная (fastest). Для длинных слов добавляется more/most, а не суффикс.'),
    ('Пассивный залог (be + V3) в английском используется вдвое чаще, чем в русском — особенно в официальных текстах, научных статьях и новостях.'),
    ('«Used to» и «would» оба описывают прошлые привычки, но только «used to» подходит для прошлых состояний: «I used to live in London» ✓, «I would live in London» ✗.'),
    ('Модальные глаголы (can, must, should…) никогда не имеют окончания -s в 3-м лице: «he can», не «he cans». Это исключение из общего правила.'),
    ('Правило «i before e, except after c» имеет столько исключений (weird, seize, their), что лингвисты считают его скорее вредным, чем полезным.'),
    ('«Will» и «be going to» — оба о будущем, но «will» — спонтанное решение, «be going to» — уже запланированное. «I''ll answer the phone» vs «I''m going to call him later».'),
    ('Инверсия в вопросах (Are you? Does he? Did she?) — обязательна в английском, тогда как в разговорном русском вопрос строится интонацией без перестановки слов.'),
    ('Каузатив «have something done» (I had my hair cut) означает, что действие делают за тебя. Это отдельная грамматическая конструкция, которой нет в большинстве языков.'),
    ('Условные предложения делятся на «нулевое» (реальный факт), «первое» (реальное будущее), «второе» (нереальное настоящее) и «третье» (невозможное прошлое). Смешанные кондишналы объединяют второе и третье.'),
    ('Reported speech (косвенная речь) сдвигает время назад: «I am tired» → He said he was tired. Это называется «sequence of tenses» и строго соблюдается в формальном языке.'),
    ('Существительные в английском не имеют рода — только местоимения: he/she/it. В древнеанглийском род был: «wīf» (женщина) был среднего рода.'),
    ('«Few» и «little» означают «мало», но «a few» и «a little» — «немного, и это хорошо». Артикль меняет коннотацию с негативной на позитивную.'),
    ('Tag questions (isn''t it? don''t you? can they?) автоматически инвертируют полярность: утвердительная фраза → отрицательный тэг, и наоборот. В русском этого нет — используем «правда?» для всего.'),
    ('Разница between «since» и «for» с Present Perfect: since = с конкретного момента («since Monday»), for = продолжительность («for three days»).'),
    ('Stative verbs (know, love, believe, own) обычно не используются в Continuous: «I am knowing» — ошибка. Это потому что они выражают состояние, а не активный процесс.'),
    ('«Despite» и «although» оба выражают уступку, но синтаксис разный: despite + noun/gerund, although + clause. «Despite being tired, I worked» = «Although I was tired, I worked».'),
    ('Двойной объект: «Give me the book» = «Give the book to me». Первый порядок (IO + DO) возможен только с короткими местоимениями, второй — универсален.'),
    ('Разделительный вопрос на «I am» звучит «aren''t I?» — грамматическая аномалия. Логично было бы «amn''t I», но эта форма вытеснена в большинстве диалектов.'),
    ('«Make» и «let» — каузативные глаголы без «to»: «She made him apologize», «He let me go». После «allow» и «permit» — уже с «to».'),
    ('Артикль «the» произносится как /ðə/ перед согласными и /ðiː/ перед гласными: «the car» /ðəkɑː/, «the apple» /ðiːˈæpəl/. Многие учащиеся этого не замечают.'),
    ('Cleft sentences («It was John who called») помогают выделить информацию, делая акцент. Русский использует для этого ударение и порядок слов.'),
    ('Герундий после предлогов обязателен: «good at swimming», «interested in learning», «before going». После предлогов инфинитив невозможен.'),
    ('Разница «say» и «tell»: tell требует объекта-получателя («tell him»), say — нет («say it»). «He said that…» ✓, «He told that…» ✗.'),
    ('«By» в пассивных предложениях вводит деятеля: «The book was written by Tolstoy». Но деятель упоминается лишь в 20% пассивных предложений — в остальных он неизвестен или неважен.'),
    ('Infinitive of purpose («I went there to buy milk») — сокращение «in order to». Полная форма звучит формально, краткая — нейтрально.'),
    ('«Even though» (даже хотя) сильнее «although» — подчёркивает неожиданность уступки. «Even if» — гипотетическое условие: «Even if I tried, I''d fail».'),
    ('«So» + прилагательное/наречие, «such» + существительное: «so beautiful», «such beauty». Ошибка «so beautiful girl» — среди самых частых у русскоязычных.'),
    ('Разница «each» и «every»: each — по отдельности (each student got a book), every — как группа (every student passed). Грамматически оба с единственным числом.'),
    ('Предлог «at» в «at the age of 30», «at night», «at Christmas» — указывает на точку во времени или условии. «In the morning», «in December» — на период.'),
    ('«Wish» + Past Simple выражает желание изменить настоящее: «I wish I knew». «Wish» + Past Perfect — о прошлом: «I wish I had known». Это сослагательное наклонение в чистом виде.'),
    ('Эллипсис — опускание повторяющихся элементов: «She can play piano and he can too» (второй «play piano» опущен). В разговорном английском это норма.'),
    ('Inversions для выразительности: «Never have I seen such beauty» — порядок вспомогательного и подлежащего перевёрнут. Используется в книжной речи и риторике.'),
    ('«Both…and», «either…or», «neither…nor» — парные союзы. «Neither…nor» с двумя ед.ч. субъектами требует ед.ч. глагола: «Neither John nor Mary is here».'),
    ('Разница «must» и «have to»: must — внутренняя обязанность (я сам считаю нужным), have to — внешняя (правила, обстоятельства). «I must try harder» vs «I have to wear a uniform».'),
    ('«Need» может быть модальным («You needn''t come») или обычным глаголом («You don''t need to come»). Значение одинаковое, но с модальным звучит формальнее.'),
    ('Существительные, исторически являвшиеся глаголами, называются «conversion» или «zero derivation»: «to email» → «an email», «to google» → «a google».'),
    ('«The» перед прилагательными в роли существительного: «the rich», «the poor», «the elderly» — группа людей. Всегда во множественном числе.'),
    ('Разница «although» / «though» / «even though»: все три — уступительные, но «even though» — самый эмфатический. «Though» в конце предложения — разговорная конструкция.'),
    ('«There is/are» — грамматическое подлежащее «there», а реальное — после глагола. «There are many reasons» — reasons реальное подлежащее, определяет число.'),
    ('Инфинитив с частицей «to» после прилагательных: «happy to help», «easy to understand», «hard to forget». Логическое подлежащее инфинитива — главное подлежащее предложения.'),
    ('«Hardly», «barely», «scarcely» — отрицательные по смыслу наречия, поэтому с «any» (не «no»): «I hardly have any time», не «I hardly have no time» (двойное отрицание).'),
    ('Разница «see», «look at», «watch»: see — непроизвольное восприятие, look at — направленный взгляд, watch — наблюдение за движением/изменением. «I saw a bird / looked at the picture / watched the game».'),
    ('Participle clauses сокращают придаточные: «Having finished the report, she left» = «After she had finished the report, she left». Требует общего субъекта с главным предложением.')
) AS f(body)
WHERE NOT EXISTS (
    SELECT 1 FROM lumi_facts
    WHERE course_code = 'en_ru' AND context = 'grammar'
);

INSERT INTO lumi_facts (course_code, context, locale, body)
SELECT 'es_ru', 'grammar', 'ru', f.body
FROM (VALUES
    ('В испанском два глагола «быть»: «ser» — для постоянных качеств (национальность, профессия, материал), «estar» — для временных состояний и местоположения. Выбор между ними меняет смысл: «Es aburrido» (он скучный человек) ≠ «Está aburrido» (ему сейчас скучно).'),
    ('Испанский — язык с развитой системой субъюнктива (сослагательного наклонения). Он используется после глаголов желания, сомнения, эмоций: «Quiero que vengas» (Хочу, чтобы ты пришёл).'),
    ('В испанском четыре прошедших времени в изъявительном наклонении: pretérito perfecto, pretérito indefinido, imperfecto и pluscuamperfecto. Каждое — для своего сценария.'),
    ('Испанский — язык «pro-drop»: подлежащее-местоимение можно опустить, если оно ясно из окончания глагола. «Hablo español» (без «yo») — нормально, а не упрощённо.'),
    ('Восклицательные и вопросительные знаки в испанском ставятся в начале предложения перевёрнутыми (¡ и ¿) и в конце обычными. Это помогает сразу понять интонацию длинного предложения.'),
    ('Reflexive глаголы (verbos reflexivos) в испанском значительно шире, чем возвратные в русском: «levantarse» (вставать), «quedarse» (оставаться) — «se» не всегда означает «себя».'),
    ('Испанские прилагательные согласуются с существительным в роде и числе: «un libro rojo», «una camisa roja», «libros rojos». Это отличает испанский от английского, где прилагательные не изменяются.'),
    ('Личные местоимения второго лица в испанском: «tú» (неформальное «ты»), «usted» (формальное «вы»), «vosotros/as» (множественное неформальное, только в Испании), «ustedes» (формальное или неформальное «вы» в Латинской Америке).'),
    ('«Gustar» и похожие глаголы (encantar, molestar, parecer) работают «наоборот»: субъект — то, что нравится, а человек стоит в дательном падеже. «Me gusta el café» = «Кофе нравится мне» (дословно).'),
    ('Двойное отрицание в испанском — норма, а не ошибка: «No vi a nadie» (Я никого не видел) — два отрицания усиливают друг друга, а не отменяют.'),
    ('Претерит (indefinido) vs имперфект (imperfecto): indefinido — завершённое действие в прошлом («Ayer comí pizza»), imperfecto — фоновое состояние или повторяющееся действие («Cuando era niño, comía pizza cada semana»).'),
    ('В испанском три класса глаголов по инфинитиву: -ar (hablar), -er (comer), -ir (vivir). Большинство правил спряжения различаются именно по этим классам.'),
    ('«Por» и «para» — оба переводятся «для/по/за», но логика разная: por — причина, обмен, продолжительность; para — цель, получатель, дедлайн. «Lo hice por amor» (из любви) vs «Lo hice para ti» (для тебя).'),
    ('Герундий (gerundio) в испанском — только для образования Estar + gerundio (Progressive): «Estoy hablando». В роли подлежащего или после предлогов используется инфинитив, а не герундий (в отличие от английского).'),
    ('«Ser» с прилагательным обозначает постоянное свойство, «estar» — временное: «La sopa es caliente» (суп горячий по природе) — ошибка, правильно «La sopa está caliente» (суп сейчас горячий).'),
    ('Прямое и косвенное дополнение в испанском используют предлог «a» перед одушевлёнными существительными: «Veo a María» (Вижу Марию). Это называется «personal a» и не имеет аналога в русском.'),
    ('Клитики (clíticos) — короткие местоимения me, te, le, lo, la, nos, os, les, los, las — стоят перед спрягаемым глаголом или после инфинитива/герундия: «Lo veo» или «Quiero verlo».'),
    ('«Hace + время + que» — стандартная конструкция для «уже N времени»: «Hace tres años que vivo aquí» (Я живу здесь уже три года). Порядок и предлог отличаются от английского.'),
    ('Будущее время в испанском образуется добавлением окончаний к инфинитиву: hablar → hablaré, hablarás, hablará… Это одна из причин, почему испанское будущее называют «слитным».'),
    ('Условное наклонение (condicional) образуется так же, как будущее, только с другими окончаниями (-ía, -ías…): «Comería más si pudiera» (Я бы ел больше, если бы мог).'),
    ('«Ir a + infinitivo» — разговорный способ выразить ближайшее будущее: «Voy a estudiar esta noche» (Я собираюсь учиться сегодня вечером). Аналог английского «be going to».'),
    ('Apocope — укорачивание слова перед существительным: «buen» вместо «bueno», «gran» вместо «grande», «algún» вместо «alguno». Это особенность испанской грамматики.'),
    ('Испанский претерит совершенного вида (perfecto) используется по-разному в Испании и Латинской Америке: в Испании — для действий с связью с настоящим, в Латинской Америке — почти исключительно indefinido для прошлого.'),
    ('В испанском прилагательные обычно стоят после существительного: «un libro interesante». Но некоторые прилагательные меняют смысл в зависимости от позиции: «un pobre hombre» (несчастный) vs «un hombre pobre» (бедный).'),
    ('«Haber» vs «tener»: haber — вспомогательный глагол для Perfect (He comido), tener — «иметь» (Tengo hambre). Путать их — классическая ошибка.'),
    ('Субъюнктив в придаточных времени: после «cuando» при указании на будущее нужен субъюнктив: «Cuando llegues, llámame» (Когда приедешь, позвони). После «cuando» в значении прошлого — изъявительное.'),
    ('«Aunque» может использоваться и с изъявительным, и с субъюнктивом: «Aunque llueve» (несмотря на то, что идёт дождь — факт) vs «Aunque llueva» (даже если пойдёт дождь — гипотеза).'),
    ('Испанские числительные: «uno» перед существительным мужского рода становится «un» (un libro), перед женского — «una» (una mesa). Во множественном числе — «unos/unas» как неопределённый артикль.'),
    ('«Deber + infinitivo» — должен, «deber de + infinitivo» — вероятно. «Debe estudiar» (он должен учиться) vs «Debe de estar cansado» (наверное, он устал). Во многих диалектах разграничение стирается.'),
    ('Испанское причастие (participio) не изменяется в составе Perfect (He comido, He bebido), но согласуется в роде и числе, когда выступает прилагательным: «La carta escrita».'),
    ('«Llevar + gerundio» выражает продолжительность действия: «Llevo dos horas esperando» (Я жду уже два часа). Эту конструкцию нет в английском — там используется Present Perfect Continuous.'),
    ('Отрицание в испанском всегда стоит прямо перед глаголом: «No quiero ir». Двойное отрицание с «nadie/nada/nunca» — норма: «No sé nada» (Я ничего не знаю).'),
    ('Притяжательные местоимения в испанском имеют краткую (mi libro) и полную форму (el libro mío). Полная форма стоит после существительного и более эмфатична.'),
    ('«Si» (если) в условных предложениях: реальное условие → изъявительное («Si estudias, aprobarás»), нереальное → субъюнктив («Si estudiaras, aprobarías»), невозможное прошлое → плюсквамперфект субъюнктива.'),
    ('Испанские глаголы движения + герундий — передают сопутствующее действие: «Salió corriendo» (Он выбежал — букв. «вышел бегом»). Это идиоматичнее, чем дословный перевод.'),
    ('«Tan» + прилагательное/наречие и «tanto/a» + существительное: «Es tan rápido como tú» (Он такой же быстрый, как ты) vs «Tiene tanto dinero como tú» (У него столько же денег, как у тебя).'),
    ('Превосходная степень в испанском: el/la más + прилагательное: «el más inteligente». Но «mejor/peor/mayor/menor» — уже сами сравнительные, без «más»: «el mejor» (лучший).'),
    ('«Cuyo/cuya/cuyos/cuyas» — притяжательное относительное местоимение (чей): «La mujer cuyo hijo ganó el premio» (Женщина, чей сын выиграл приз). Согласуется с объектом, а не с субъектом.'),
    ('Порядок клитиков при двух местоимениях: сначала косвенное, потом прямое — «me lo», «te la», «se lo». Два клитика 3-го лица: «le lo» → «se lo» (чтобы избежать неприятного звучания).'),
    ('Imperativo (повелительное) имеет разные формы для «tú» и «usted»: «habla» (tú) vs «hable» (usted). Для «vosotros» — особая форма: «hablad». В отрицании — всегда субъюнктив.'),
    ('«Acabar de + infinitivo» — только что сделал: «Acabo de comer» (Я только что поел). «Acabar + gerundio» — в конечном счёте: «Acabó comprando el coche» (В итоге он купил машину).'),
    ('Испанские безличные предложения с «se»: «Se habla español» (Говорят по-испански / Здесь говорят по-испански). Это пассив без деятеля — очень частая конструкция.'),
    ('«Estar» + participio выражает результативное состояние: «La tienda está cerrada» (Магазин закрыт — в состоянии закрытости). «Ser» + participio — пассивный залог: «La tienda fue cerrada por el dueño».'),
    ('Испанские вопросительные слова всегда пишутся с ударением: ¿qué? ¿quién? ¿cuándo? ¿dónde? ¿cómo? ¿por qué? ¿cuánto? В косвенном вопросе акцент тоже сохраняется.'),
    ('«Hace + время» для давности в прошлом: «Hace tres años fui a España» (Три года назад я ездил в Испанию). В сочетании с «que» и Perfect — продолжение до сейчас: «Hace tres años que vivo aquí».'),
    ('«Mismo/a» усиливает подлежащее (yo mismo = я сам) или выражает тождество (el mismo libro = та же самая книга). Позиция в предложении определяет смысл.'),
    ('Diminutivos (-ito/-ita) в испанском — не только уменьшительное значение, но и эмоциональная окраска (ласка, вежливость): «Espérate un momentito» (Подожди секундочку — мягче, чем «momento»).'),
    ('«Haber que + infinitivo» (hay que, había que) — безличная обязанность: «Hay que estudiar» (Нужно учиться — неопределённо, «все должны»). «Tener que» — личная обязанность: «Tengo que estudiar».'),
    ('Augmentatives (-ón/-ona, -azo/-aza) увеличивают или усиливают: «un cochazo» (шикарная тачка), «un golpazo» (сильный удар). Иногда имеют пейоративный оттенок: «hombrón» (здоровяк, с иронией).'),
    ('«Mientras» с изъявительным — одновременное действие в прошлом/настоящем; с субъюнктивом — гипотетическое или будущее: «Mientras estudias» (пока ты учишься) vs «Mientras estudies» (пока будешь учиться).')
) AS f(body)
WHERE NOT EXISTS (
    SELECT 1 FROM lumi_facts
    WHERE course_code = 'es_ru' AND context = 'grammar'
);
